// Guard against fetch failures
const fetchResults = [
  { name: 'Events', data: $('Fetch Unprocessed Events').first().json },
  { name: 'Projects', data: $('Fetch Active Projects').first().json },
  { name: 'Brands', data: $('Fetch Brands').first().json }
];
const fetchErrors = [];
for (const fr of fetchResults) {
  if (fr.data.error || fr.data.statusCode >= 400 || (fr.data.statusMessage && fr.data.statusCode)) {
    fetchErrors.push(`${fr.name}: ${fr.data.error || fr.data.statusMessage || 'HTTP ' + fr.data.statusCode}`);
  }
}
if (fetchErrors.length > 0) {
  return [{ json: { decisions: [], eventIds: [], decisionCount: 0, eventCount: 0, _error: true, fetchErrors } }];
}

const events = $('Fetch Unprocessed Events').first().json.records || [];
const projects = $('Fetch Active Projects').first().json.records || [];
const brands = $('Fetch Brands').first().json.records || [];
const now = new Date();
const decisions = [];
const eventIds = [];

for (const event of events) {
  const f = event.fields;
  eventIds.push(event.id);

  const project = projects.find(p => p.id === f.project_id);
  const brand = brands.find(b => b.fields.brand_name === f.brand_name);
  let payload = {};
  try { payload = JSON.parse(f.payload || '{}'); } catch(e) {}

  switch (f.event_type) {
    case 'phase_complete':
      if (f.agent === 'phase_1') {
        decisions.push({
          type: 'notify_client',
          event: f,
          eventId: event.id,
          message: 'Research complete for ' + f.brand_name + ' \u2014 concepts ready for PM review',
          project_id: f.project_id,
          brand_name: f.brand_name,
          client_code: f.client_code
        });
      }
      if (f.agent === 'phase_2') {
        decisions.push({
          type: 'trigger_phase',
          phase: 3,
          event: f,
          eventId: event.id,
          webhook: '/webhook/ugc-scripts',
          message: 'Concepts approved for ' + f.brand_name + ' \u2014 triggering script writing',
          project_id: f.project_id,
          brand_name: f.brand_name,
          client_code: f.client_code
        });
        decisions.push({
          type: 'notify_client',
          event: f,
          eventId: event.id,
          message: 'Concepts approved for ' + f.brand_name + ', scripts being generated',
          project_id: f.project_id,
          brand_name: f.brand_name,
          client_code: f.client_code
        });
      }
      if (f.agent === 'phase_3') {
        decisions.push({
          type: 'trigger_phase',
          phase: 4,
          event: f,
          eventId: event.id,
          webhook: '/webhook/ugc-delivery',
          message: 'Scripts ready for ' + f.brand_name + ' \u2014 triggering delivery',
          project_id: f.project_id,
          brand_name: f.brand_name,
          client_code: f.client_code
        });
        decisions.push({
          type: 'notify_client',
          event: f,
          eventId: event.id,
          message: 'Scripts ready for review for ' + f.brand_name,
          project_id: f.project_id,
          brand_name: f.brand_name,
          client_code: f.client_code
        });
      }
      if (f.agent === 'phase_4') {
        decisions.push({
          type: 'notify_client',
          event: f,
          eventId: event.id,
          message: 'Delivery complete for ' + f.brand_name + '!',
          project_id: f.project_id,
          brand_name: f.brand_name,
          client_code: f.client_code
        });
      }
      break;

    case 'campaign_alert':
      if (payload.fatigued_count > 0) {
        const deliveredProject = projects.find(p =>
          p.fields.brand_name === f.brand_name &&
          (p.fields.status === 'Delivered' || p.fields.status === 'Complete')
        );
        if (deliveredProject) {
          decisions.push({
            type: 'suggest_new_cycle',
            event: f,
            eventId: event.id,
            message: 'Ad fatigue detected for ' + f.brand_name + ' \u2014 ' + payload.fatigued_count + ' campaigns fatigued. Consider new creative cycle.',
            project_id: deliveredProject.id,
            brand_name: f.brand_name,
            client_code: f.client_code
          });
        }
      }
      if (f.severity === 'critical') {
        decisions.push({
          type: 'escalate',
          event: f,
          eventId: event.id,
          severity: 'critical',
          message: 'CRITICAL: ROAS crash for ' + f.brand_name + ' \u2014 immediate action needed. ' + (payload.recommendation || ''),
          brand_name: f.brand_name
        });
      }
      break;

    case 'lead_action':
      if (payload.stage === 'Won') {
        decisions.push({
          type: 'auto_onboard',
          event: f,
          eventId: event.id,
          message: 'Lead won: ' + (f.brand_name || payload.company) + ' \u2014 ready for onboarding',
          brand_name: f.brand_name || payload.company,
          client_code: f.client_code
        });
      }
      break;

    case 'sla_breach': {
      const recentBreaches = events.filter(e =>
        e.fields.event_type === 'sla_breach' && e.fields.project_id === f.project_id
      );
      if (recentBreaches.length >= 3) {
        decisions.push({
          type: 'escalate',
          event: f,
          eventId: event.id,
          severity: 'critical',
          message: 'REPEATED SLA BREACH: ' + f.brand_name + ' has ' + recentBreaches.length + ' breaches \u2014 needs immediate attention',
          project_id: f.project_id,
          brand_name: f.brand_name,
          client_code: f.client_code
        });
      }
      break;
    }

    case 'status_change':
      if (f.agent === 'onboarding') {
        decisions.push({
          type: 'notify_client',
          event: f,
          eventId: event.id,
          message: 'New project onboarded for ' + f.brand_name + ' \u2014 research phase starting soon',
          project_id: f.project_id,
          brand_name: f.brand_name,
          client_code: f.client_code
        });
      }
      break;
  }
}

// SLA detection from project status
for (const project of projects) {
  const pf = project.fields;
  const updatedAt = new Date(pf.updated_at || pf.created_at || now);
  const hoursInStatus = (now - updatedAt) / 3600000;

  if (pf.status === 'PM Review' && hoursInStatus > 24) {
    decisions.push({
      type: 'sla_alert',
      severity: 'warning',
      project_id: project.id,
      brand_name: pf.brand_name,
      client_code: pf.client_code,
      message: pf.brand_name + ' stuck in PM Review for ' + Math.round(hoursInStatus) + 'h'
    });
  }
  if (pf.status === 'Script Review' && hoursInStatus > 48) {
    decisions.push({
      type: 'sla_alert',
      severity: 'warning',
      project_id: project.id,
      brand_name: pf.brand_name,
      client_code: pf.client_code,
      message: pf.brand_name + ' stuck in Script Review for ' + Math.round(hoursInStatus) + 'h'
    });
  }
  if (pf.status === 'In Progress' && hoursInStatus > 72) {
    decisions.push({
      type: 'sla_alert',
      severity: 'urgent',
      project_id: project.id,
      brand_name: pf.brand_name,
      client_code: pf.client_code,
      message: pf.brand_name + ' In Progress for ' + Math.round(hoursInStatus) + 'h \u2014 may be stuck'
    });
  }
}

return [{ json: { decisions, eventIds, decisionCount: decisions.length, eventCount: events.length } }];

